// Provided for labs 14.1 and 14.2. You do not edit this file (Metal host side). Ours.
// Encodes the in-place exclusive scan of scan.metal, the Metal counterpart of scan.cu:
//
//   int scanScratchCount(int count)
//       unsigned ints of scratch the scan needs for `count` elements (at least 1).
//   bool encodeExclusiveScan(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> data,
//                            uint32_t count, id<MTLBuffer> scratch)
//       In place: data[0] = 0 and data[i] = (old) data[0] + ... + data[i-1]. count >= 1; the
//       sum of all `count` elements must fit in 32 bits; scratch holds scanScratchCount(count)
//       elements. Encodes 1, 3 or 5 dispatches (the same counts as scan.cu) into enc and
//       returns false, encoding nothing, if a scan kernel does not build or cannot run 256
//       threads per threadgroup.
//
// It sets its own pipelines and buffers, so the caller must set everything again for its own
// next dispatch. An encoder made with plain computeCommandEncoder runs its dispatches serially,
// and buffers made from the device are hazard-tracked, so each dispatch sees the previous one's
// writes (notes/today/ch02-facts.md C9).
//
// The pipelines are compiled from scan.metal in this directory. The course runtime compiles
// and caches them (pmpp/metal.h); an application would build them once from a library.
#import <Metal/Metal.h>
#include <cstdint>
#include <string>

#include "pmpp/metal.h"

static const uint32_t kScanBlock = 256;   // SCAN_BLOCK_DIM in scan.metal
static const uint32_t kScanTile = 1024;   // SCAN_TILE

static id<MTLComputePipelineState> scanPipeline(const char* name) {
    // PMPP_METAL_SHARED_DIR is <chapter>/shared; this lab group's provided files are in shared-g11.
    return pmpp::metal::pipeline(std::string(PMPP_METAL_SHARED_DIR) + "-g11/scan.metal", name);
}

static uint32_t scanTileCount(uint32_t count) { return (count + kScanTile - 1) / kScanTile; }
static uint32_t scanRoundUp4(uint32_t x) { return (x + 3) / 4 * 4; }

int scanScratchCount(int count) {
    uint32_t c = count > 0 ? (uint32_t)count : 1u;
    uint32_t total = 0;
    while (c > kScanTile) {
        c = scanTileCount(c);
        total += scanRoundUp4(c);
    }
    return total > 0 ? (int)total : 1;
}

// One level: scan the tiles of the `count` elements at `offset` bytes into `buf`, scan their
// totals (which go to scratch at `scratchOffset`), add them back. Offsets are multiples of 16.
static void encodeLevel(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> scanTile,
                        id<MTLComputePipelineState> addOffsets, id<MTLBuffer> buf, NSUInteger offset,
                        uint32_t count, id<MTLBuffer> scratch, NSUInteger scratchOffset) {
    const uint32_t tiles = scanTileCount(count);
    const uint32_t wantTotals = tiles > 1 ? 1u : 0u;
    [enc setComputePipelineState:scanTile];
    [enc setBuffer:buf offset:offset atIndex:0];
    [enc setBuffer:scratch offset:scratchOffset atIndex:1];
    [enc setBytes:&count length:sizeof(count) atIndex:2];
    [enc setBytes:&wantTotals length:sizeof(wantTotals) atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake(tiles, 1, 1) threadsPerThreadgroup:MTLSizeMake(kScanBlock, 1, 1)];
    if (tiles == 1) {
        return;
    }
    const NSUInteger levelBytes = (NSUInteger)scanRoundUp4(tiles) * sizeof(uint32_t);
    encodeLevel(enc, scanTile, addOffsets, scratch, scratchOffset, tiles, scratch, scratchOffset + levelBytes);
    [enc setComputePipelineState:addOffsets];
    [enc setBuffer:buf offset:offset atIndex:0];
    [enc setBuffer:scratch offset:scratchOffset atIndex:1];
    [enc setBytes:&count length:sizeof(count) atIndex:2];
    [enc dispatchThreadgroups:MTLSizeMake(tiles, 1, 1) threadsPerThreadgroup:MTLSizeMake(kScanBlock, 1, 1)];
}

bool encodeExclusiveScan(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> data, uint32_t count, id<MTLBuffer> scratch) {
    id<MTLComputePipelineState> scanTile = scanPipeline("scan_tile");
    id<MTLComputePipelineState> addOffsets = scanPipeline("add_tile_offsets");
    if (!scanTile || !addOffsets || count == 0) {
        return false;
    }
    if (scanTile.maxTotalThreadsPerThreadgroup < kScanBlock || addOffsets.maxTotalThreadsPerThreadgroup < kScanBlock) {
        return false;
    }
    encodeLevel(enc, scanTile, addOffsets, data, 0, count, scratch, 0);
    return true;
}
